  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "Ranitidine absolute oral bioavailability was 88 ± 10% in healthy volunteers after a 20 mg oral dose versus IV, directly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Didanosine absolute oral bioavailability was approximately 43% in patients (40–45% across study days), supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Thalidomide oral bioavailability was probably high (80–100%) at low doses in fasting healthy volunteers, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Nitecapone oral bioavailability was 38–59% in healthy volunteers, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Tegafur oral bioavailability was almost 100% in humans, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C39"],
      "claim": "Chloramphenicol oral bioavailability is described as excellent, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Nevirapine absolute oral bioavailability was 91 ± 8% in healthy volunteers, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Tivantinib oral bioavailability was ≥20%, meeting the threshold and supporting high.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Didanosine oral solution with antacid at 120 mg/m2 in children had F=19%, a subthreshold value; this is a high-dose pediatric formulation-specific observation.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is nitrofurantoin, a small nitrofuran hydantoin. Highly transferable experimental evidence from ranitidine, didanosine, nitecapone, thalidomide, tegafur, chloramphenicol, nevirapine, and tivantinib overwhelmingly shows oral bioavailability at or above 20%, with most values 40–100%. The single subthreshold didanosine pediatric record (19%) is formulation/dose-specific and outweighed by multiple adult absolute bioavailability values >25%. Therefore F ≥ 20% is supported.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule was supplied; prediction relies on transferable analogues.",
    "The supplied transfer scores are uniformly high but do not encode structural similarity, so mechanistic extrapolation is indirect.",
    "One pediatric didanosine record (19%) is below threshold and should be interpreted cautiously due to age, dose, and formulation effects."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

